// What the parts of the BlitzPlus GUI share: the tables of gadgets, menus and tree nodes, and the helpers that the
// parts use of each other. Nothing in here is for programs, those only see the functions of the Blitz API.
//
// The GUI is made of gadgets that are drawn and handled by the runtime itself, on the same renderer that Graphics
// uses. Windows are drawn inside of the one window of the program, as the renderer has only one. Everything is
// written with the functions that programs have for 2D drawing, so that it is drawn wherever the renderer draws.
#pragma once
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "scene.hpp"

extern "C" {
void    bb_runtime_error(const char* message);
void    bb_event_post(int32_t kind, int32_t data, int32_t x, int32_t y, int32_t z, int32_t source);
int32_t bb_create_image(int32_t width, int32_t height, int32_t frames);
void    bb_free_image(int32_t handle);
int32_t bb_image_width(int32_t handle);
int32_t bb_image_height(int32_t handle);
int32_t bb_image_buffer(int32_t handle, int32_t frame);
int32_t bb_load_image(const char* file);
}

namespace bb::gui {
	using bb::buffer;

	////////////////////////////////////////////////////////////////////////////
	// Event kinds, the numbers that BlitzPlus uses
	////////////////////////////////////////////////////////////////////////////
	constexpr int event_key_down      = 0x101;
	constexpr int event_key_up        = 0x102;
	constexpr int event_key_char      = 0x103;
	constexpr int event_mouse_down    = 0x201;
	constexpr int event_mouse_up      = 0x202;
	constexpr int event_mouse_move    = 0x203;
	constexpr int event_mouse_wheel   = 0x204;
	constexpr int event_mouse_enter   = 0x205;
	constexpr int event_mouse_leave   = 0x206;
	constexpr int event_gadget_action = 0x401;
	constexpr int event_window_move   = 0x801;
	constexpr int event_window_size   = 0x802;
	constexpr int event_window_close  = 0x803;
	constexpr int event_window_active = 0x804;
	constexpr int event_menu_action   = 0x1001;
	constexpr int event_begin_modal   = 0x2004;
	constexpr int event_end_modal     = 0x2005;

	////////////////////////////////////////////////////////////////////////////
	// What there is
	////////////////////////////////////////////////////////////////////////////
	enum kind {
		K_DESKTOP,
		K_WINDOW,
		K_PANEL,
		K_LABEL,
		K_BUTTON,
		K_TEXTFIELD,
		K_TEXTAREA,
		K_LISTBOX,
		K_COMBOBOX,
		K_TABBER,
		K_TREEVIEW,
		K_SLIDER,
		K_PROGBAR,
		K_TOOLBAR,
		K_CANVAS,
	};

	// Handles tell what they are for, so that a gadget can't be taken for a timer or a menu.
	constexpr int gadget_base = 0x04000000;
	constexpr int menu_base   = 0x05000000;
	constexpr int node_base   = 0x06000000;
	constexpr int strip_base  = 0x07000000;

	struct list_item {
		char* text = nullptr;
		int   icon = -1;
	};

	// How a part of a text area looks: colors, and bold and italic.
	struct text_format {
		int pos = 0, len = 0;
		int r = 0, g = 0, b = 0, flags = 0;
	};

	struct gadget {
		bool used = false;
		int  kind = K_PANEL, style = 0;
		int  parent = 0; // The group that it is in.
		int  x = 0, y = 0, w = 0, h = 0; // In the client area of the group, for windows on the desktop.
		bool visible = false, enabled = true;
		int  font = 0;
		char* text = nullptr;
		int  strip = 0; // Icon strip.
		buffer<int> kids;

		// The layout, which says how the gadget follows its group when that changes size.
		int left = 0, right = 0, top = 0, bottom = 0;
		int ox = 0, oy = 0, ow = 0, oh = 0, gw = 1, gh = 1;

		// The size of the client area, for gadgets that have children.
		int cw = 0, ch = 0;

		// Buttons, sliders and progress bars
		int   state = 0; // Button state, slider value
		int   range_visible = 0, range_total = 0;
		float progress = 0;

		// Lists (list boxes, combo boxes and tabbers)
		buffer<list_item> items;
		int               selected = -1;
		int               scroll   = 0; // First row that is seen.
		bool              open     = false; // Combo box: the list is shown.

		// Panels
		bool has_color = false;
		int  color[3]  = { 0, 0, 0 };
		int  image     = 0;

		// Text fields and text areas
		int         caret = 0, anchor = 0; // Where the cursor is, and where the selection started.
		int         scroll_x = 0, scroll_y = 0;
		int         tabs = 4, locked = 0;
		int         text_color[3] = { 0, 0, 0 }, back_color[3] = { 255, 255, 255 };
		bool        has_back = false, has_text_color = false;
		buffer<text_format> formats;
		bool        changed_by_program = false;

		// Tree views
		int root = 0, selected_node = 0;

		// Toolbars
		buffer<char> tool_enabled; // For each button.
		buffer<char> tool_blank;   // For each icon: whether it is a space between buttons.
		char*        tips = nullptr;
		int          tool_hot = -1;

		// Windows
		int  menu = 0;
		char* status = nullptr;
		int  min_w = 0, min_h = 0;
		bool minimized = false, maximized = false;
		int  restore_x = 0, restore_y = 0, restore_w = 0, restore_h = 0;

		// Canvases: the image that is drawn to, and whether it is waiting to be shown.
		int canvas_image = 0;
		int canvas_flipped = 0;
	};

	struct menu {
		bool used = false;
		int  parent = 0;
		char* text = nullptr;
		int  tag = 0;
		bool checked = false, enabled = true;
		buffer<int> kids;
	};

	struct node {
		bool used = false;
		int  tree = 0;   // Gadget that it is in.
		int  parent = 0; // Node, 0 for the root of the tree.
		char* text = nullptr;
		int  icon = -1;
		bool expanded = false;
		buffer<int> kids;
	};

	struct icon_strip {
		bool used = false;
		int  image = 0;
		int  count = 0, size = 0;
	};

	////////////////////////////////////////////////////////////////////////////
	// Tables and helpers (gui_core.cpp)
	////////////////////////////////////////////////////////////////////////////
	extern bool gui_used; // Whether a program has made a gadget, which is when this takes over the window.

	char*   copy_string(const char* s);
	char*   string_result(const char* s); // A string for the program, which has its length in front.
	void    set_string(char*& field, const char* value);
	gadget* gadget_of(int handle);
	gadget* need_gadget(int handle, const char* what);
	gadget* need_kind(int handle, int kind, const char* what);
	int     handle_of(gadget const* g);
	int     create_gadget(int kind, int style, int group, const char* what);
	int     make_gadget(int kind, int style, int group, int x, int y, int w, int h, const char* what);
	void    lock_layout(gadget& g);
	void    perform_layout(gadget& g);
	void    set_shape(int handle, int x, int y, int w, int h);
	void    update_client(int handle);
	int     desktop_handle();
	int     desktop_buffer();
	void    screen_size(int* w, int* h); // Of the display that the program is on, the graphics size without one.
	void    client_rect(int handle, int* x, int* y, int* w, int* h); // Relative to the gadget.
	void    absolute_position(int handle, int* x, int* y);           // Of the top left of the gadget, on the screen.
	void    absolute_client(int handle, int* x, int* y);             // Of the top left of its client area.
	bool    shown(int handle);                                       // Whether it and everything it is in is visible.
	int     window_of(int handle);
	int     active_window();
	void    set_active_window(int handle, bool post);
	void    gui_error(const char* message);
	void    dirty();

	menu*   menu_of(int handle);
	node*   node_of(int handle);
	icon_strip* strip_of(int handle);
	void    free_gadget_tree(int handle);
	extern buffer<gadget*> gadgets;
	extern buffer<menu*>   menus;
	extern buffer<node*>   nodes;
	extern buffer<icon_strip*> strips;

	int     window_menu_root(int window);
	void    free_node(int handle);
	void    free_menu_tree(int handle);

	// The sizes that windows have around the client area.
	constexpr int title_height  = 24;
	constexpr int menu_height   = 22;
	constexpr int status_height = 22;
	constexpr int frame_width   = 4;
	constexpr int tab_height    = 26;

	// Tool windows (style 16) have a thinner title with a close box only, like the small caption of Windows.
	constexpr int tool_title_height = 16;
	inline int    title_bar_height(gadget const& g) { return (g.style & 16) ? tool_title_height : title_height; }
	inline int    title_box_width(gadget const& g) { return (g.style & 16) ? 14 : 18; }
	inline int    title_box_height(gadget const& g) { return (g.style & 16) ? 12 : 16; }

	void window_decoration(gadget const& g, int* left, int* top, int* right, int* bottom);

	////////////////////////////////////////////////////////////////////////////
	// Drawing and handling (gui_render.cpp and gui_input.cpp)
	////////////////////////////////////////////////////////////////////////////
	constexpr int bar_width = 16; // Of the scroll bars of lists.

	// A line of a text area as it is shown: wrapped text has more of them than it has lines.
	struct visual_line {
		int start = 0, length = 0;
	};

	struct tree_row {
		int node = 0, depth = 0;
	};

	// What the person using the program is doing right now.
	struct ui_state {
		int         focus = 0;   // The gadget that typing goes to.
		int         pressed = 0; // The gadget that a mouse button is held on.
		int         hover = 0;   // The gadget that the mouse is over.
		int         combo = 0;   // The combo box whose list is open.
		int         menu_window = 0;
		buffer<int> menu_path; // The menus that are open, from the bar to the deepest.
		int         modal = 0; // Whether a requester is shown, which is when nothing else can be used.
	};
	extern ui_state ui;

	void update();
	bool handle_event(void const* sdl_event); // Says whether the gadgets used it.
	bool translate(int kind, int* x, int* y, int* source);
	extern bool (*modal_handler)(void const* sdl_event); // While a requester is shown it gets everything.
	extern void (*overlay_draw)();                       // What is drawn on top of the gadgets, before they are shown.
	void render();
	void ensure_graphics();
	int  font_size(gadget const& g);
	int  row_height(gadget const& g);
	int  text_width(gadget const& g, const char* text, int length);
	int  text_height(gadget const& g);
	int  field_x(gadget const& g, int index);                              // Where the cursor of a text field is, in pixels from the start of its text.
	int  char_at(gadget const& g, const char* text, int length, int x);   // Which boundary between characters is closest to a position.
	int  fit_chars(gadget const& g, const char* text, int length, int width); // How many characters fit in a width.
	void clamp_scroll(gadget& g);
	void caret_to_view(gadget& g);
	void post_action(int handle, int data, int x = 0, int y = 0);
	void post_to(int kind, int handle, int data, int x = 0, int y = 0, int z = 0);
	int  count_visible_nodes(gadget const& g);
	void select_item(int handle, int index, bool user);
	void select_tree_node(int handle, bool user);
	void expand_node(int handle, bool expand);
	int  tab_client_rect(gadget const& g, int* x, int* y, int* w, int* h);
	void set_text_field(gadget& g, const char* text);
	void text_area_insert(gadget& g, int pos, int len, const char* text);
	int  text_area_length(gadget const& g);
	int  line_start(gadget const& g, int line);
	int  line_count(gadget const& g);
	int  line_of(gadget const& g, int pos);
	void normalize_text(const char* text, char** out, int* length);

	// Where things are, which drawing and handling the mouse both need. Positions are in the window of the program.
	void content_rect(gadget const& g, int* x, int* y, int* w, int* h);   // Where the rows or the text of a gadget are.
	void scroll_rect(gadget const& g, int* x, int* y, int* w, int* h);    // The scroll bar of a list, text area or tree.
	void hscroll_rect(gadget const& g, int* x, int* y, int* w, int* h);   // The bar along the bottom of a text area whose lines are longer than it is wide.
	bool has_hbar(gadget const& g);
	int  longest_line_width(gadget const& g); // In pixels, of the lines of a text area.
	void scroll_thumb(int position, int visible, int total, int length, int* start, int* size);
	int  visible_rows(gadget const& g);
	int  total_rows(gadget const& g);
	void build_lines(gadget const& g, buffer<visual_line>& out);
	void build_tree_rows(gadget const& g, buffer<tree_row>& out);
	int  slider_limit(gadget const& g);
	bool slider_horizontal(gadget const& g);
	void tab_rect(gadget const& g, int index, int* x, int* y, int* w, int* h);
	void tool_button_rect(gadget const& g, int icon, int* x, int* y, int* w, int* h);
	int  tool_button_index(gadget const& g, int icon); // The number that events say, -1 for a space.
	void menu_bar_rect(int window, int index, int* x, int* y, int* w, int* h); // Relative to the window.
	void menu_popup_rect(int window, int level, int* x, int* y, int* w, int* h);
	int  menu_row_height();
	int  window_buttons(gadget const& g, int* close_x, int* max_x, int* min_x, int* y); // Relative to the window.
	void minimized_rect(int window, int* x, int* y, int* w, int* h);
	void text_changed(int handle, int key);
} // namespace bb::gui
